UPDATE protocol_command_outbox outbox_row
JOIN marketing_task_send_attempt attempt
  ON attempt.command_id = outbox_row.command_id
 AND attempt.tenant_id = #{tenantId}
SET outbox_row.status = #{canceledStatus},
    outbox_row.last_error = 'TASK_RELEASED',
    outbox_row.updated_at = #{now}
WHERE attempt.marketing_task_id = #{marketingTaskId}
  AND outbox_row.tenant_id = #{tenantId}
  AND attempt.status = 0
  AND outbox_row.deleted_at IS NULL
  AND outbox_row.status = #{pendingStatus}

UPDATE protocol_command_outbox
SET status = #{canceledStatus},
    last_error = 'MANUAL_OFFLINE',
    updated_at = #{now}
WHERE aggregate_type = #{aggregateType}
  AND aggregate_id IN

  #{accountId}

  AND command_type = #{onlineCommandType}
  AND status = #{pendingStatus}
  AND deleted_at IS NULL

UPDATE protocol_command_outbox
SET status = CASE
      WHEN status = #{dispatchingStatus} THEN #{cancelRequestedStatus}
      ELSE #{canceledStatus}
    END,
    last_error = #{lastError},
    updated_at = #{now}
WHERE (status IN
#{status}
  OR status = #{dispatchingStatus})
  AND deleted_at IS NULL
  AND (
    (aggregate_type = #{accountActionAggregateType} AND EXISTS (
      SELECT 1
      FROM pull_task_account_action action_row
      WHERE action_row.id = protocol_command_outbox.aggregate_id
        AND action_row.task_id = #{taskId}

          AND action_row.group_execution_id = #{executionId}

    ))
    OR (aggregate_type = #{pullCallAggregateType} AND EXISTS (
      SELECT 1
      FROM pull_task_pull_call call_row
      WHERE call_row.id = protocol_command_outbox.aggregate_id
        AND call_row.task_id = #{taskId}

          AND call_row.group_execution_id = #{executionId}

    ))
    OR (aggregate_type = #{materialAggregateType} AND EXISTS (
      SELECT 1
      FROM pull_task_material_member material_row
      JOIN pull_task_group_execution execution_row
        ON execution_row.id = material_row.group_execution_id
      WHERE material_row.id = protocol_command_outbox.aggregate_id
        AND execution_row.task_id = #{taskId}

          AND execution_row.id = #{executionId}

    ))
    OR (aggregate_type = #{memberQueryAggregateType} AND EXISTS (
      SELECT 1
      FROM pull_task_member_query query_row
      WHERE query_row.id = protocol_command_outbox.aggregate_id
        AND query_row.task_id = #{taskId}

          AND query_row.group_execution_id = #{executionId}

    ))
  )

